import os, json

d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
session_path = d + '/../../sessions/' + os.path.basename(d) + '.jsonl'
with open(session_path, 'r') as f:
    lines = f.readlines()

found_plain_action = []

for i, line in enumerate(lines):
    try:
        msg = json.loads(line.strip())
        if msg.get('type') != 'message':
            continue

        inner_msg = msg.get('message', {})
        if inner_msg.get('role') != 'assistant':
            continue

        content = inner_msg.get('content', [])

        # Check if has text but NOT thinking
        has_thinking = False
        has_text = False

        for item in content:
            itype = item.get('type')
            if itype == 'thinking':
                has_thinking = True
            elif itype == 'text':
                has_text = True

        # If has text AND no thinking, check for action at end
        if has_text and not has_thinking:
            for item in content:
                if item.get('type') == 'text':
                    text = item.get('text', '').rstrip()
                    print(f"\nPlain text found at line {i}:")
                    print(f"  Length: {len(text)}")
                    if text.endswith('}'):
                        print(f"  ENDS WITH: ...{text[-100:]}")
                        found_plain_action.append((i, text))

    except:
        pass

print(f"\n\nTotal plain text assistant messages with action at end: {len(found_plain_action)}")

